/* One reading, as the driver took it. */
typedef struct {
  uint32_t ms;
  int16_t x, y;
  uint16_t z1;
} TouchCapReading;

typedef struct {
  const char *name;
  const TouchCapReading *readings;
  size_t count;
} TouchCapSet;

